LANGS = ['hi', 'bn', 'mr', 'te', 'ta', 'es', 'pt', 'id', 'ar']

T = {
 "Face the camera, feet wide, with your head and hips visible.": ["कैमरे की ओर मुँह करें, पैर चौड़े, सिर और कूल्हे दिखें।", "ক্যামেরার দিকে মুখ করুন, পা চওড়া, মাথা ও নিতম্ব দেখা যাক।", "कॅमेऱ्याकडे तोंड करा, पाय रुंद, डोके आणि नितंब दिसतील.", "కెమెరా వైపు తిరగండి, పాదాలు వెడల్పుగా, తల, తుంటి కనిపించాలి.", "கேமராவைப் பாருங்கள், பாதங்கள் அகலமாக, தலையும் இடுப்பும் தெரிய வேண்டும்.", "De frente a la cámara, pies separados, con cabeza y caderas visibles.", "De frente para a câmera, pés afastados, com cabeça e quadris visíveis.", "Hadap kamera, kaki lebar, kepala dan pinggul terlihat.", "واجه الكاميرا وقدماك متباعدتان، بحيث يظهر الرأس والوركان."],
 "Lie side-on, knees bent, with shoulders, hips and knees visible.": ["बगल से लेटें, घुटने मुड़े, कंधे, कूल्हे और घुटने दिखें।", "পাশ ফিরে শুয়ে, হাঁটু ভাঁজ করে, কাঁধ, নিতম্ব ও হাঁটু দেখা যাক।", "बाजूने झोपा, गुडघे वाकवलेले, खांदे, नितंब आणि गुडघे दिसतील.", "పక్కగా పడుకోండి, మోకాళ్లు వంచి, భుజాలు, తుంటి, మోకాళ్లు కనిపించాలి.", "பக்கவாட்டில் படுங்கள், முழங்கால்கள் மடித்து, தோள்கள், இடுப்பு, முழங்கால்கள் தெரிய வேண்டும்.", "Túmbate de lado, rodillas flexionadas, con hombros, caderas y rodillas visibles.", "Deite de lado, joelhos dobrados, com ombros, quadris e joelhos visíveis.", "Berbaring menyamping, lutut ditekuk, bahu, pinggul, dan lutut terlihat.", "استلقِ جانبيًا والركبتان مثنيتان، بحيث تظهر الكتفان والوركان والركبتان."],
 "Either leg counts.": ["कोई भी टाँग गिनी जाती है।", "যেকোনো পা গোনা হয়।", "कोणताही पाय मोजला जातो.", "ఏ కాలైనా లెక్కే.", "எந்தக் காலும் கணக்கே.", "Cuenta cualquier pierna.", "Qualquer perna conta.", "Kaki mana pun dihitung.", "تُحتسب أي ساق."],
 "Hands and knees, side-on, with shoulders, hips and knees visible.": ["हाथों और घुटनों के बल, बगल से, कंधे, कूल्हे और घुटने दिखें।", "হাত ও হাঁটুর ওপর, পাশ থেকে, কাঁধ, নিতম্ব ও হাঁটু দেখা যাক।", "हात आणि गुडघ्यांवर, बाजूने, खांदे, नितंब आणि गुडघे दिसतील.", "చేతులు, మోకాళ్లపై, పక్కగా, భుజాలు, తుంటి, మోకాళ్లు కనిపించాలి.", "கைகளிலும் முழங்கால்களிலும், பக்கவாட்டில், தோள்கள், இடுப்பு, முழங்கால்கள் தெரிய வேண்டும்.", "A cuatro patas, de lado, con hombros, caderas y rodillas visibles.", "De quatro, de lado, com ombros, quadris e joelhos visíveis.", "Posisi merangkak, menyamping, bahu, pinggul, dan lutut terlihat.", "على اليدين والركبتين، جانبيًا، بحيث تظهر الكتفان والوركان والركبتان."],
 "Hands on a sturdy table or bench, side-on, with your arm and hip visible.": ["हाथ मज़बूत मेज़ या बेंच पर, बगल से, बाँह और कूल्हा दिखे।", "হাত শক্ত টেবিল বা বেঞ্চে, পাশ থেকে, হাত ও নিতম্ব দেখা যাক।", "हात भक्कम टेबल किंवा बाकावर, बाजूने, हात आणि नितंब दिसतील.", "చేతులు గట్టి బల్ల లేదా బెంచ్‌పై, పక్కగా, చేయి, తుంటి కనిపించాలి.", "கைகள் உறுதியான மேசை அல்லது பெஞ்சில், பக்கவாட்டில், கையும் இடுப்பும் தெரிய வேண்டும்.", "Manos en una mesa o banco firme, de lado, con brazo y cadera visibles.", "Mãos numa mesa ou banco firme, de lado, com braço e quadril visíveis.", "Tangan di meja atau bangku yang kokoh, menyamping, lengan dan pinggul terlihat.", "اليدان على طاولة أو مقعد ثابت، جانبيًا، بحيث تظهر الذراع والورك."],
 "Knees on the floor, side-on, with your head to knees visible.": ["घुटने ज़मीन पर, बगल से, सिर से घुटनों तक दिखें।", "হাঁটু মেঝেতে, পাশ থেকে, মাথা থেকে হাঁটু পর্যন্ত দেখা যাক।", "गुडघे जमिनीवर, बाजूने, डोक्यापासून गुडघ्यांपर्यंत दिसेल.", "మోకాళ్లు నేలపై, పక్కగా, తల నుండి మోకాళ్ల వరకు కనిపించాలి.", "முழங்கால்கள் தரையில், பக்கவாட்டில், தலை முதல் முழங்கால் வரை தெரிய வேண்டும்.", "Rodillas en el suelo, de lado, visible de la cabeza a las rodillas.", "Joelhos no chão, de lado, visível da cabeça aos joelhos.", "Lutut di lantai, menyamping, terlihat dari kepala hingga lutut.", "الركبتان على الأرض، جانبيًا، ويظهر الجسم من الرأس إلى الركبتين."],
 "Hinge forward, side-on, with your arm and hip visible.": ["आगे झुकें, बगल से, बाँह और कूल्हा दिखे।", "সামনে ঝুঁকুন, পাশ থেকে, হাত ও নিতম্ব দেখা যাক।", "पुढे वाका, बाजूने, हात आणि नितंब दिसतील.", "ముందుకు వంగండి, పక్కగా, చేయి, తుంటి కనిపించాలి.", "முன்னோக்கிக் குனியுங்கள், பக்கவாட்டில், கையும் இடுப்பும் தெரிய வேண்டும்.", "Inclínate hacia delante, de lado, con brazo y cadera visibles.", "Incline-se para a frente, de lado, com braço e quadril visíveis.", "Condongkan badan ke depan, menyamping, lengan dan pinggul terlihat.", "انحنِ للأمام جانبيًا، بحيث تظهر الذراع والورك."],
 "Lie face down, side-on, with shoulders, hips and knees visible.": ["पेट के बल लेटें, बगल से, कंधे, कूल्हे और घुटने दिखें।", "উপুড় হয়ে শুয়ে, পাশ থেকে, কাঁধ, নিতম্ব ও হাঁটু দেখা যাক।", "पोटावर झोपा, बाजूने, खांदे, नितंब आणि गुडघे दिसतील.", "బోర్లా పడుకోండి, పక్కగా, భుజాలు, తుంటి, మోకాళ్లు కనిపించాలి.", "குப்புறப் படுங்கள், பக்கவாட்டில், தோள்கள், இடுப்பு, முழங்கால்கள் தெரிய வேண்டும்.", "Túmbate boca abajo, de lado, con hombros, caderas y rodillas visibles.", "Deite de bruços, de lado, com ombros, quadris e joelhos visíveis.", "Berbaring tengkurap, menyamping, bahu, pinggul, dan lutut terlihat.", "استلقِ على بطنك جانبيًا، بحيث تظهر الكتفان والوركان والركبتان."],
 "Stand side-on, with your arm and hip visible and room above your hand.": ["बगल से खड़े हों, बाँह और कूल्हा दिखे और हाथ के ऊपर जगह रहे।", "পাশ ফিরে দাঁড়ান, হাত ও নিতম্ব দেখা যাক, হাতের ওপরে জায়গা থাকুক।", "बाजूने उभे राहा, हात आणि नितंब दिसतील आणि हाताच्या वर जागा राहील.", "పక్కకు నిలబడండి, చేయి, తుంటి కనిపించాలి, చేతి పైన చోటు ఉండాలి.", "பக்கவாட்டில் நில்லுங்கள், கையும் இடுப்பும் தெரிய, கைக்கு மேலே இடம் இருக்கட்டும்.", "Ponte de lado, con brazo y cadera visibles y espacio por encima de la mano.", "Fique de lado, com braço e quadril visíveis e espaço acima da mão.", "Berdiri menyamping, lengan dan pinggul terlihat, dan ada ruang di atas tangan.", "قف جانبيًا بحيث تظهر الذراع والورك مع مساحة فوق يدك."],
 "Face the camera or stand side-on, with your arm and hip visible.": ["कैमरे की ओर मुँह करें या बगल से खड़े हों, बाँह और कूल्हा दिखे।", "ক্যামেরার দিকে মুখ করুন বা পাশ ফিরে দাঁড়ান, হাত ও নিতম্ব দেখা যাক।", "कॅमेऱ्याकडे तोंड करा किंवा बाजूने उभे राहा, हात आणि नितंब दिसतील.", "కెమెరా వైపు తిరగండి లేదా పక్కకు నిలబడండి, చేయి, తుంటి కనిపించాలి.", "கேமராவைப் பார்த்து அல்லது பக்கவாட்டில் நில்லுங்கள், கையும் இடுப்பும் தெரிய வேண்டும்.", "De frente a la cámara o de lado, con brazo y cadera visibles.", "De frente para a câmera ou de lado, com braço e quadril visíveis.", "Hadap kamera atau menyamping, lengan dan pinggul terlihat.", "قف مواجهًا للكاميرا أو جانبيًا بحيث تظهر الذراع والورك."],
 "Stand side-on, with your arm and hip visible.": ["बगल से खड़े हों, बाँह और कूल्हा दिखे।", "পাশ ফিরে দাঁড়ান, হাত ও নিতম্ব দেখা যাক।", "बाजूने उभे राहा, हात आणि नितंब दिसतील.", "పక్కకు నిలబడండి, చేయి, తుంటి కనిపించాలి.", "பக்கவாட்டில் நில்லுங்கள், கையும் இடுப்பும் தெரிய வேண்டும்.", "Ponte de lado, con brazo y cadera visibles.", "Fique de lado, com braço e quadril visíveis.", "Berdiri menyamping, lengan dan pinggul terlihat.", "قف جانبيًا بحيث تظهر الذراع والورك."],
 "Face the camera, with your shoulders, elbows and hips visible.": ["कैमरे की ओर मुँह करें, कंधे, कोहनियाँ और कूल्हे दिखें।", "ক্যামেরার দিকে মুখ করুন, কাঁধ, কনুই ও নিতম্ব যেন দেখা যায়।", "कॅमेऱ्याकडे तोंड करा, खांदे, कोपर आणि नितंब दिसतील असे.", "కెమెరా వైపు తిరగండి, భుజాలు, మోచేతులు, తుంటి కనిపించాలి.", "கேமராவைப் பாருங்கள், தோள்கள், முழங்கைகள், இடுப்பு தெரிய வேண்டும்.", "De frente a la cámara, con hombros, codos y caderas visibles.", "De frente para a câmera, com ombros, cotovelos e quadris visíveis.", "Hadap kamera, dengan bahu, siku, dan pinggul terlihat.", "واجه الكاميرا بحيث تظهر الكتفان والمرفقان والوركان."],
 "Lie side-on, with shoulders, hips and knees visible.": ["बगल से लेटें, कंधे, कूल्हे और घुटने दिखें।", "পাশ ফিরে শুয়ে, কাঁধ, নিতম্ব ও হাঁটু দেখা যাক।", "बाजूने झोपा, खांदे, नितंब आणि गुडघे दिसतील.", "పక్కగా పడుకోండి, భుజాలు, తుంటి, మోకాళ్లు కనిపించాలి.", "பக்கவாட்டில் படுங்கள், தோள்கள், இடுப்பு, முழங்கால்கள் தெரிய வேண்டும்.", "Túmbate de lado, con hombros, caderas y rodillas visibles.", "Deite de lado, com ombros, quadris e joelhos visíveis.", "Berbaring menyamping, bahu, pinggul, dan lutut terlihat.", "استلقِ جانبيًا بحيث تظهر الكتفان والوركان والركبتان."],
 "Stand far back, side-on, so your whole body stays in frame.": ["दूर पीछे बगल से खड़े हों, ताकि पूरा शरीर फ़्रेम में रहे।", "অনেকটা পিছিয়ে পাশ ফিরে দাঁড়ান, যাতে পুরো শরীর ফ্রেমে থাকে।", "खूप मागे बाजूने उभे राहा, म्हणजे पूर्ण शरीर चौकटीत राहील.", "బాగా వెనక్కి పక్కగా నిలబడండి, శరీరం మొత్తం ఫ్రేమ్‌లో ఉండేలా.", "நன்றாகப் பின்னால் பக்கவாட்டில் நில்லுங்கள், முழு உடலும் சட்டகத்தில் இருக்கட்டும்.", "Ponte lejos y de lado, para que todo tu cuerpo quede en el encuadre.", "Fique bem para trás e de lado, para o corpo todo caber no quadro.", "Berdiri jauh di belakang, menyamping, agar seluruh tubuh tetap dalam bingkai.", "قف بعيدًا وجانبيًا ليبقى جسمك كله داخل الإطار."],
 "Push-up position, side-on, with shoulders, hips and knees visible.": ["पुश-अप स्थिति, बगल से, कंधे, कूल्हे और घुटने दिखें।", "পুশ-আপ অবস্থান, পাশ থেকে, কাঁধ, নিতম্ব ও হাঁটু দেখা যাক।", "पुश-अप स्थिती, बाजूने, खांदे, नितंब आणि गुडघे दिसतील.", "పుష్-అప్ స్థితి, పక్కగా, భుజాలు, తుంటి, మోకాళ్లు కనిపించాలి.", "புஷ்-அப் நிலை, பக்கவாட்டில், தோள்கள், இடுப்பு, முழங்கால்கள் தெரிய வேண்டும்.", "Posición de flexión, de lado, con hombros, caderas y rodillas visibles.", "Posição de flexão, de lado, com ombros, quadris e joelhos visíveis.", "Posisi push-up, menyamping, bahu, pinggul, dan lutut terlihat.", "وضعية الضغط، جانبيًا، بحيث تظهر الكتفان والوركان والركبتان."],
 "Face the camera or stand side-on.": ["कैमरे की ओर मुँह करें या बगल से खड़े हों।", "ক্যামেরার দিকে মুখ করুন বা পাশ ফিরে দাঁড়ান।", "कॅमेऱ्याकडे तोंड करा किंवा बाजूने उभे राहा.", "కెమెరా వైపు తిరగండి లేదా పక్కకు నిలబడండి.", "கேமராவைப் பாருங்கள் அல்லது பக்கவாட்டில் நில்லுங்கள்.", "De frente a la cámara o de lado.", "De frente para a câmera ou de lado.", "Hadap kamera atau menyamping.", "واجه الكاميرا أو قف جانبيًا."],
 "Stand side-on or face the camera, with your feet in frame and room above your head.": ["बगल से खड़े हों या कैमरे की ओर मुँह करें, पैर फ़्रेम में और सिर के ऊपर जगह हो।", "পাশ ফিরে দাঁড়ান বা ক্যামেরার দিকে মুখ করুন, পা ফ্রেমে ও মাথার ওপরে জায়গা থাকুক।", "बाजूने उभे राहा किंवा कॅमेऱ्याकडे तोंड करा, पाय चौकटीत आणि डोक्यावर जागा असेल.", "పక్కకు నిలబడండి లేదా కెమెరా వైపు తిరగండి, పాదాలు ఫ్రేమ్‌లో, తల పైన చోటు ఉండాలి.", "பக்கவாட்டில் நில்லுங்கள் அல்லது கேமராவைப் பாருங்கள், பாதங்கள் சட்டகத்தில், தலைக்கு மேலே இடம் இருக்கட்டும்.", "De lado o de frente a la cámara, con los pies en el encuadre y espacio sobre la cabeza.", "De lado ou de frente para a câmera, com os pés no quadro e espaço acima da cabeça.", "Menyamping atau hadap kamera, kaki dalam bingkai dan ada ruang di atas kepala.", "قف جانبيًا أو مواجهًا للكاميرا، وقدماك في الإطار ومساحة فوق رأسك."],
 "Stand side-on, with your hips, knees and hands visible.": ["बगल से खड़े हों, कूल्हे, घुटने और हाथ दिखें।", "পাশ ফিরে দাঁড়ান, নিতম্ব, হাঁটু ও হাত দেখা যাক।", "बाजूने उभे राहा, नितंब, गुडघे आणि हात दिसतील.", "పక్కకు నిలబడండి, తుంటి, మోకాళ్లు, చేతులు కనిపించాలి.", "பக்கவாட்டில் நில்லுங்கள், இடுப்பு, முழங்கால்கள், கைகள் தெரிய வேண்டும்.", "Ponte de lado, con caderas, rodillas y manos visibles.", "Fique de lado, com quadris, joelhos e mãos visíveis.", "Berdiri menyamping, pinggul, lutut, dan tangan terlihat.", "قف جانبيًا بحيث تظهر الوركان والركبتان واليدان."],
 "Stand side-on.": ["बगल से खड़े हों।", "পাশ ফিরে দাঁড়ান।", "बाजूने उभे राहा.", "పక్కకు నిలబడండి.", "பக்கவாட்டில் நில்லுங்கள்.", "Ponte de lado.", "Fique de lado.", "Berdiri menyamping.", "قف جانبيًا."],
 "Stand side-on with the weight across your shoulders.": ["बगल से खड़े हों, वज़न कंधों पर।", "পাশ ফিরে দাঁড়ান, ওজন কাঁধের ওপর।", "बाजूने उभे राहा, वजन खांद्यांवर.", "పక్కకు నిలబడండి, బరువు భుజాలపై.", "பக்கவாட்டில் நில்லுங்கள், எடை தோள்களில்.", "Ponte de lado con el peso sobre los hombros.", "Fique de lado com o peso sobre os ombros.", "Berdiri menyamping dengan beban di bahu.", "قف جانبيًا والوزن على كتفيك."],
 "Stand side-on with a dumbbell in each hand and your feet clearly visible.": ["बगल से खड़े हों, दोनों हाथों में एक-एक डंबल, पैर साफ़ दिखें।", "পাশ ফিরে দাঁড়ান, দুই হাতে ডাম্বেল, পা স্পষ্ট দেখা যাক।", "बाजूने उभे राहा, प्रत्येक हातात एक डंबेल, पाय स्पष्ट दिसतील.", "పక్కకు నిలబడండి, ఒక్కో చేతిలో డంబెల్, పాదాలు స్పష్టంగా కనిపించాలి.", "பக்கவாட்டில் நில்லுங்கள், ஒவ்வொரு கையிலும் டம்பெல், பாதங்கள் தெளிவாகத் தெரிய வேண்டும்.", "Ponte de lado con una mancuerna en cada mano y los pies bien visibles.", "Fique de lado com um halter em cada mão e os pés bem visíveis.", "Berdiri menyamping dengan dumbel di tiap tangan dan kaki terlihat jelas.", "قف جانبيًا ودمبل في كل يد وقدماك ظاهرتان بوضوح."],
 "Lie side-on, knees bent, with the weight on your hips.": ["बगल से लेटें, घुटने मुड़े, वज़न कूल्हों पर।", "পাশ ফিরে শুয়ে, হাঁটু ভাঁজ, ওজন নিতম্বে।", "बाजूने झोपा, गुडघे वाकवलेले, वजन नितंबांवर.", "పక్కగా పడుకోండి, మోకాళ్లు వంచి, బరువు తుంటిపై.", "பக்கவாட்டில் படுங்கள், முழங்கால்கள் மடித்து, எடை இடுப்பில்.", "Túmbate de lado, rodillas flexionadas, con el peso sobre la cadera.", "Deite de lado, joelhos dobrados, com o peso sobre o quadril.", "Berbaring menyamping, lutut ditekuk, beban di pinggul.", "استلقِ جانبيًا والركبتان مثنيتان والوزن على وركيك."],
 "Lie on a bench or the floor, side-on, with your arm and hip visible.": ["बेंच या ज़मीन पर बगल से लेटें, बाँह और कूल्हा दिखे।", "বেঞ্চে বা মেঝেতে পাশ থেকে শুয়ে, হাত ও নিতম্ব দেখা যাক।", "बाकावर किंवा जमिनीवर बाजूने झोपा, हात आणि नितंब दिसतील.", "బెంచ్ లేదా నేలపై పక్కగా పడుకోండి, చేయి, తుంటి కనిపించాలి.", "பெஞ்சில் அல்லது தரையில் பக்கவாட்டில் படுங்கள், கையும் இடுப்பும் தெரிய வேண்டும்.", "Túmbate en un banco o en el suelo, de lado, con brazo y cadera visibles.", "Deite num banco ou no chão, de lado, com braço e quadril visíveis.", "Berbaring di bangku atau lantai, menyamping, lengan dan pinggul terlihat.", "استلقِ على مقعد أو الأرض جانبيًا بحيث تظهر الذراع والورك."],
 "Lie side-on, upper arms pointing up, with your arm and hip visible.": ["बगल से लेटें, ऊपरी बाँहें ऊपर की ओर, बाँह और कूल्हा दिखे।", "পাশ ফিরে শুয়ে, ওপরের হাত ওপরমুখী, হাত ও নিতম্ব দেখা যাক।", "बाजूने झोपा, दंड वरच्या दिशेने, हात आणि नितंब दिसतील.", "పక్కగా పడుకోండి, పై చేతులు పైకి, చేయి, తుంటి కనిపించాలి.", "பக்கவாட்டில் படுங்கள், மேல் கைகள் மேல்நோக்கி, கையும் இடுப்பும் தெரிய வேண்டும்.", "Túmbate de lado, brazos apuntando hacia arriba, con brazo y cadera visibles.", "Deite de lado, braços apontando para cima, com braço e quadril visíveis.", "Berbaring menyamping, lengan atas mengarah ke atas, lengan dan pinggul terlihat.", "استلقِ جانبيًا والعضدان متّجهان للأعلى، بحيث تظهر الذراع والورك."],
 "Hinge forward, side-on or facing the camera, arms long.": ["आगे झुकें, बगल से या कैमरे की ओर मुँह करके, बाँहें लंबी।", "সামনে ঝুঁকুন, পাশ থেকে বা ক্যামেরার দিকে মুখ করে, হাত লম্বা।", "पुढे वाका, बाजूने किंवा कॅमेऱ्याकडे तोंड करून, हात लांब.", "ముందుకు వంగండి, పక్కగా లేదా కెమెరా వైపు, చేతులు చాచి.", "முன்னோக்கிக் குனியுங்கள், பக்கவாட்டில் அல்லது கேமராவைப் பார்த்து, கைகள் நீட்டி.", "Inclínate hacia delante, de lado o de frente a la cámara, brazos largos.", "Incline-se para a frente, de lado ou de frente para a câmera, braços longos.", "Condongkan badan ke depan, menyamping atau hadap kamera, lengan lurus.", "انحنِ للأمام جانبيًا أو مواجهًا للكاميرا، والذراعان ممدودتان."],
 "Sit tall, side-on, pulling a band or cable towards your waist.": ["सीधे बैठें, बगल से, बैंड या केबल को कमर की ओर खींचें।", "সোজা হয়ে বসুন, পাশ থেকে, ব্যান্ড বা কেবল কোমরের দিকে টানুন।", "ताठ बसा, बाजूने, बँड किंवा केबल कंबरेकडे ओढा.", "నిటారుగా కూర్చోండి, పక్కగా, బ్యాండ్ లేదా కేబుల్‌ను నడుము వైపు లాగండి.", "நிமிர்ந்து அமருங்கள், பக்கவாட்டில், பேண்ட் அல்லது கேபிளை இடுப்பை நோக்கி இழுங்கள்.", "Siéntate erguido, de lado, tirando de una banda o polea hacia la cintura.", "Sente-se ereto, de lado, puxando um elástico ou cabo em direção à cintura.", "Duduk tegak, menyamping, tarik pita atau kabel ke arah pinggang.", "اجلس مستقيمًا جانبيًا واسحب حبلًا مطاطيًا أو كابلًا نحو خصرك."],
 "Sit leaning forward, elbow on your inner thigh, with your arm visible.": ["आगे झुककर बैठें, कोहनी जाँघ के अंदर, बाँह दिखे।", "সামনে ঝুঁকে বসুন, কনুই ঊরুর ভেতরে, হাত দেখা যাক।", "पुढे झुकून बसा, कोपर मांडीच्या आतल्या बाजूला, हात दिसेल.", "ముందుకు వంగి కూర్చోండి, మోచేయి లోపలి తొడపై, చేయి కనిపించాలి.", "முன்னோக்கிச் சாய்ந்து அமருங்கள், முழங்கை உள் தொடையில், கை தெரிய வேண்டும்.", "Siéntate inclinado hacia delante, codo en la cara interna del muslo, con el brazo visible.", "Sente-se inclinado para a frente, cotovelo na parte interna da coxa, com o braço visível.", "Duduk condong ke depan, siku di paha dalam, lengan terlihat.", "اجلس مائلًا للأمام والمرفق على باطن فخذك، بحيث تظهر الذراع."],
 "Face the camera or stand side-on, with room above your hands.": ["कैमरे की ओर मुँह करें या बगल से खड़े हों, हाथों के ऊपर जगह हो।", "ক্যামেরার দিকে মুখ করুন বা পাশ ফিরে দাঁড়ান, হাতের ওপরে জায়গা থাকুক।", "कॅमेऱ्याकडे तोंड करा किंवा बाजूने उभे राहा, हातांच्या वर जागा असेल.", "కెమెరా వైపు తిరగండి లేదా పక్కకు నిలబడండి, చేతుల పైన చోటు ఉండాలి.", "கேமராவைப் பார்த்து அல்லது பக்கவாட்டில் நில்லுங்கள், கைகளுக்கு மேலே இடம் இருக்கட்டும்.", "De frente a la cámara o de lado, con espacio sobre las manos.", "De frente para a câmera ou de lado, com espaço acima das mãos.", "Hadap kamera atau menyamping, dengan ruang di atas tangan.", "قف مواجهًا للكاميرا أو جانبيًا مع مساحة فوق يديك."],
 "Hips high in an upside-down V, side-on, with your arm and hip visible.": ["कूल्हे ऊपर, उल्टे V जैसे, बगल से, बाँह और कूल्हा दिखे।", "নিতম্ব উঁচু, উল্টো V-এর মতো, পাশ থেকে, হাত ও নিতম্ব দেখা যাক।", "नितंब उंच, उलट्या V सारखे, बाजूने, हात आणि नितंब दिसतील.", "తుంటి పైకి, తలకిందుల V లాగా, పక్కగా, చేయి, తుంటి కనిపించాలి.", "இடுப்பு உயர்த்தி தலைகீழ் V போல, பக்கவாட்டில், கையும் இடுப்பும் தெரிய வேண்டும்.", "Caderas arriba formando una V invertida, de lado, con brazo y cadera visibles.", "Quadris no alto, num V invertido, de lado, com braço e quadril visíveis.", "Pinggul tinggi membentuk V terbalik, menyamping, lengan dan pinggul terlihat.", "الوركان مرتفعان على شكل V مقلوبة، جانبيًا، بحيث تظهر الذراع والورك."],
 "Hands on a sturdy chair behind you, side-on, knees bent.": ["हाथ पीछे मज़बूत कुर्सी पर, बगल से, घुटने मुड़े।", "হাত পেছনে শক্ত চেয়ারে, পাশ থেকে, হাঁটু ভাঁজ।", "हात मागे भक्कम खुर्चीवर, बाजूने, गुडघे वाकवलेले.", "చేతులు వెనుక గట్టి కుర్చీపై, పక్కగా, మోకాళ్లు వంచి.", "கைகள் பின்னால் உறுதியான நாற்காலியில், பக்கவாட்டில், முழங்கால்கள் மடித்து.", "Manos en una silla firme detrás de ti, de lado, rodillas flexionadas.", "Mãos numa cadeira firme atrás de você, de lado, joelhos dobrados.", "Tangan di kursi kokoh di belakang, menyamping, lutut ditekuk.", "اليدان على كرسي ثابت خلفك، جانبيًا، والركبتان مثنيتان."],
 "Hang from a sturdy bar, with your hands and shoulders visible.": ["मज़बूत बार से लटकें, हाथ और कंधे दिखें।", "শক্ত বার থেকে ঝুলুন, হাত ও কাঁধ দেখা যাক।", "भक्कम बारला लटका, हात आणि खांदे दिसतील.", "గట్టి బార్ నుండి వేలాడండి, చేతులు, భుజాలు కనిపించాలి.", "உறுதியான கம்பியில் தொங்குங்கள், கைகளும் தோள்களும் தெரிய வேண்டும்.", "Cuélgate de una barra firme, con manos y hombros visibles.", "Pendure-se numa barra firme, com mãos e ombros visíveis.", "Bergelantung di palang yang kokoh, tangan dan bahu terlihat.", "تعلّق بعارضة ثابتة بحيث تظهر اليدان والكتفان."],
 "Sit at a cable or use a band above you, side-on or facing the camera, with your hands visible.": ["केबल पर बैठें या ऊपर बँधा बैंड इस्तेमाल करें, बगल से या कैमरे की ओर मुँह करके, हाथ दिखें।", "কেবলে বসুন বা ওপরে বাঁধা ব্যান্ড ব্যবহার করুন, পাশ থেকে বা ক্যামেরার দিকে মুখ করে, হাত দেখা যাক।", "केबलवर बसा किंवा वर लावलेला बँड वापरा, बाजूने किंवा कॅमेऱ्याकडे तोंड करून, हात दिसतील.", "కేబుల్ దగ్గర కూర్చోండి లేదా పైన బ్యాండ్ వాడండి, పక్కగా లేదా కెమెరా వైపు, చేతులు కనిపించాలి.", "கேபிளில் அமருங்கள் அல்லது மேலே கட்டிய பேண்டைப் பயன்படுத்துங்கள், பக்கவாட்டில் அல்லது கேமராவைப் பார்த்து, கைகள் தெரிய வேண்டும்.", "Siéntate en una polea o usa una banda por encima, de lado o de frente a la cámara, con las manos visibles.", "Sente-se numa polia ou use um elástico acima de você, de lado ou de frente para a câmera, com as mãos visíveis.", "Duduk di mesin kabel atau pakai pita di atas, menyamping atau hadap kamera, tangan terlihat.", "اجلس عند جهاز كابل أو استخدم حبلًا مطاطيًا فوقك، جانبيًا أو مواجهًا للكاميرا، بحيث تظهر يداك."],
 "Lie side-on holding a weight above your chest, arms long.": ["बगल से लेटें, छाती के ऊपर वज़न पकड़ें, बाँहें लंबी।", "পাশ ফিরে শুয়ে, বুকের ওপরে ওজন ধরুন, হাত লম্বা।", "बाजूने झोपा, छातीवर वजन धरा, हात लांब.", "పక్కగా పడుకోండి, ఛాతీ పైన బరువు పట్టుకోండి, చేతులు చాచి.", "பக்கவாட்டில் படுங்கள், மார்புக்கு மேலே எடையைப் பிடியுங்கள், கைகள் நீட்டி.", "Túmbate de lado sujetando un peso sobre el pecho, brazos largos.", "Deite de lado segurando um peso acima do peito, braços longos.", "Berbaring menyamping memegang beban di atas dada, lengan lurus.", "استلقِ جانبيًا ممسكًا وزنًا فوق صدرك والذراعان ممدودتان."],
 "Stand side-on with room in front of you and your hips visible.": ["बगल से खड़े हों, आगे जगह हो और कूल्हे दिखें।", "পাশ ফিরে দাঁড়ান, সামনে জায়গা থাকুক ও নিতম্ব দেখা যাক।", "बाजूने उभे राहा, पुढे जागा असेल आणि नितंब दिसतील.", "పక్కకు నిలబడండి, ముందు చోటు ఉండాలి, తుంటి కనిపించాలి.", "பக்கவாட்டில் நில்லுங்கள், முன்னால் இடம் இருக்கட்டும், இடுப்பு தெரிய வேண்டும்.", "Ponte de lado con espacio delante y las caderas visibles.", "Fique de lado com espaço à frente e os quadris visíveis.", "Berdiri menyamping dengan ruang di depan dan pinggul terlihat.", "قف جانبيًا مع مساحة أمامك ويظهر الوركان."],
 "Back foot on a chair or bench, side-on, with both feet visible.": ["पिछला पैर कुर्सी या बेंच पर, बगल से, दोनों पैर दिखें।", "পেছনের পা চেয়ার বা বেঞ্চে, পাশ থেকে, দুই পা দেখা যাক।", "मागचा पाय खुर्चीवर किंवा बाकावर, बाजूने, दोन्ही पाय दिसतील.", "వెనుక పాదం కుర్చీ లేదా బెంచ్‌పై, పక్కగా, రెండు పాదాలు కనిపించాలి.", "பின் பாதம் நாற்காலி அல்லது பெஞ்சில், பக்கவாட்டில், இரு பாதங்களும் தெரிய வேண்டும்.", "Pie trasero en una silla o banco, de lado, con ambos pies visibles.", "Pé de trás numa cadeira ou banco, de lado, com os dois pés visíveis.", "Kaki belakang di kursi atau bangku, menyamping, kedua kaki terlihat.", "القدم الخلفية على كرسي أو مقعد، جانبيًا، والقدمان ظاهرتان."],
 "Stand side-on and squat on one leg, the other held out in front.": ["बगल से खड़े होकर एक टाँग पर स्क्वैट करें, दूसरी आगे फैलाएँ।", "পাশ ফিরে দাঁড়িয়ে এক পায়ে স্কোয়াট করুন, অন্য পা সামনে বাড়ান।", "बाजूने उभे राहून एका पायावर स्क्वॅट करा, दुसरा पुढे धरा.", "పక్కకు నిలబడి ఒక కాలిపై స్క్వాట్ చేయండి, మరో కాలు ముందుకు చాచండి.", "பக்கவாட்டில் நின்று ஒரு காலில் குந்துங்கள், மற்றதை முன்னால் நீட்டுங்கள்.", "Ponte de lado y haz una sentadilla a una pierna, con la otra estirada al frente.", "Fique de lado e agache numa perna só, com a outra estendida à frente.", "Berdiri menyamping dan jongkok dengan satu kaki, kaki lain lurus ke depan.", "قف جانبيًا وانزل القرفصاء على ساق واحدة والأخرى ممدودة أمامك."],
 "Lie face down, side-on, with your whole leg visible.": ["पेट के बल लेटें, बगल से, पूरी टाँग दिखे।", "উপুড় হয়ে শুয়ে, পাশ থেকে, পুরো পা দেখা যাক।", "पोटावर झोपा, बाजूने, पूर्ण पाय दिसेल.", "బోర్లా పడుకోండి, పక్కగా, కాలు మొత్తం కనిపించాలి.", "குப்புறப் படுங்கள், பக்கவாட்டில், முழுக் காலும் தெரிய வேண்டும்.", "Túmbate boca abajo, de lado, con toda la pierna visible.", "Deite de bruços, de lado, com a perna toda visível.", "Berbaring tengkurap, menyamping, seluruh kaki terlihat.", "استلقِ على بطنك جانبيًا بحيث تظهر ساقك كلها."],
 "Kick up against a wall, side-on, with your hands and hips visible.": ["दीवार के सहारे पैर ऊपर करें, बगल से, हाथ और कूल्हे दिखें।", "দেয়ালে ভর দিয়ে পা ওপরে তুলুন, পাশ থেকে, হাত ও নিতম্ব দেখা যাক।", "भिंतीला टेकून पाय वर करा, बाजूने, हात आणि नितंब दिसतील.", "గోడకు ఆనుకుని కాళ్లు పైకెత్తండి, పక్కగా, చేతులు, తుంటి కనిపించాలి.", "சுவரில் சாய்ந்து கால்களை மேலே உதையுங்கள், பக்கவாட்டில், கைகளும் இடுப்பும் தெரிய வேண்டும்.", "Sube las piernas contra una pared, de lado, con manos y caderas visibles.", "Suba as pernas contra uma parede, de lado, com mãos e quadris visíveis.", "Angkat kaki bersandar ke dinding, menyamping, tangan dan pinggul terlihat.", "اركل للأعلى مستندًا إلى جدار، جانبيًا، بحيث تظهر اليدان والوركان."],
 "Hang from a sturdy bar, side-on, with your hips and knees visible.": ["मज़बूत बार से लटकें, बगल से, कूल्हे और घुटने दिखें।", "শক্ত বার থেকে ঝুলুন, পাশ থেকে, নিতম্ব ও হাঁটু দেখা যাক।", "भक्कम बारला लटका, बाजूने, नितंब आणि गुडघे दिसतील.", "గట్టి బార్ నుండి వేలాడండి, పక్కగా, తుంటి, మోకాళ్లు కనిపించాలి.", "உறுதியான கம்பியில் தொங்குங்கள், பக்கவாட்டில், இடுப்பும் முழங்கால்களும் தெரிய வேண்டும்.", "Cuélgate de una barra firme, de lado, con caderas y rodillas visibles.", "Pendure-se numa barra firme, de lado, com quadris e joelhos visíveis.", "Bergelantung di palang kokoh, menyamping, pinggul dan lutut terlihat.", "تعلّق بعارضة ثابتة جانبيًا بحيث يظهر الوركان والركبتان."],
 "Feet on a chair or bench, side-on, with your whole body visible.": ["पैर कुर्सी या बेंच पर, बगल से, पूरा शरीर दिखे।", "পা চেয়ার বা বেঞ্চে, পাশ থেকে, পুরো শরীর দেখা যাক।", "पाय खुर्चीवर किंवा बाकावर, बाजूने, पूर्ण शरीर दिसेल.", "పాదాలు కుర్చీ లేదా బెంచ్‌పై, పక్కగా, శరీరం మొత్తం కనిపించాలి.", "பாதங்கள் நாற்காலி அல்லது பெஞ்சில், பக்கவாட்டில், முழு உடலும் தெரிய வேண்டும்.", "Pies en una silla o banco, de lado, con todo el cuerpo visible.", "Pés numa cadeira ou banco, de lado, com o corpo todo visível.", "Kaki di kursi atau bangku, menyamping, seluruh tubuh terlihat.", "القدمان على كرسي أو مقعد، جانبيًا، ويظهر جسمك كله."],
 "Kneel side-on with your ankles held down, and your whole leg visible.": ["बगल से घुटनों पर बैठें, टखने दबे हों, पूरी टाँग दिखे।", "পাশ ফিরে হাঁটু গেড়ে বসুন, গোড়ালি চেপে রাখা, পুরো পা দেখা যাক।", "बाजूने गुडघ्यांवर बसा, घोटे दाबून धरलेले, पूर्ण पाय दिसेल.", "పక్కగా మోకరిల్లండి, చీలమండలు అదిమి పెట్టి, కాలు మొత్తం కనిపించాలి.", "பக்கவாட்டில் மண்டியிடுங்கள், கணுக்கால்கள் அழுத்தப்பட்டு, முழுக் காலும் தெரிய வேண்டும்.", "Arrodíllate de lado con los tobillos sujetos y toda la pierna visible.", "Ajoelhe de lado com os tornozelos presos e a perna toda visível.", "Berlutut menyamping dengan pergelangan kaki ditahan, seluruh kaki terlihat.", "اجثُ جانبيًا والكاحلان مثبّتان، بحيث تظهر ساقك كلها."],
 "Stand side-on, with your feet in frame and room above your head.": ["बगल से खड़े हों, पैर फ़्रेम में और सिर के ऊपर जगह हो।", "পাশ ফিরে দাঁড়ান, পা ফ্রেমে ও মাথার ওপরে জায়গা থাকুক।", "बाजूने उभे राहा, पाय चौकटीत आणि डोक्यावर जागा असेल.", "పక్కకు నిలబడండి, పాదాలు ఫ్రేమ్‌లో, తల పైన చోటు ఉండాలి.", "பக்கவாட்டில் நில்லுங்கள், பாதங்கள் சட்டகத்தில், தலைக்கு மேலே இடம் இருக்கட்டும்.", "Ponte de lado, con los pies en el encuadre y espacio sobre la cabeza.", "Fique de lado, com os pés no quadro e espaço acima da cabeça.", "Berdiri menyamping, kaki dalam bingkai dan ruang di atas kepala.", "قف جانبيًا وقدماك في الإطار ومساحة فوق رأسك."],
 "Stand side-on, with your whole body in frame and room above your head.": ["बगल से खड़े हों, पूरा शरीर फ़्रेम में और सिर के ऊपर जगह हो।", "পাশ ফিরে দাঁড়ান, পুরো শরীর ফ্রেমে ও মাথার ওপরে জায়গা থাকুক।", "बाजूने उभे राहा, पूर्ण शरीर चौकटीत आणि डोक्यावर जागा असेल.", "పక్కకు నిలబడండి, శరీరం మొత్తం ఫ్రేమ్‌లో, తల పైన చోటు ఉండాలి.", "பக்கவாட்டில் நில்லுங்கள், முழு உடலும் சட்டகத்தில், தலைக்கு மேலே இடம் இருக்கட்டும்.", "Ponte de lado, con todo el cuerpo en el encuadre y espacio sobre la cabeza.", "Fique de lado, com o corpo todo no quadro e espaço acima da cabeça.", "Berdiri menyamping, seluruh tubuh dalam bingkai dan ruang di atas kepala.", "قف جانبيًا وجسمك كله في الإطار ومساحة فوق رأسك."],
 "Stand side-on with room above your hand and your hips visible.": ["बगल से खड़े हों, हाथ के ऊपर जगह हो और कूल्हे दिखें।", "পাশ ফিরে দাঁড়ান, হাতের ওপরে জায়গা থাকুক ও নিতম্ব দেখা যাক।", "बाजूने उभे राहा, हाताच्या वर जागा असेल आणि नितंब दिसतील.", "పక్కకు నిలబడండి, చేతి పైన చోటు ఉండాలి, తుంటి కనిపించాలి.", "பக்கவாட்டில் நில்லுங்கள், கைக்கு மேலே இடம் இருக்கட்டும், இடுப்பு தெரிய வேண்டும்.", "Ponte de lado con espacio sobre la mano y las caderas visibles.", "Fique de lado com espaço acima da mão e os quadris visíveis.", "Berdiri menyamping dengan ruang di atas tangan dan pinggul terlihat.", "قف جانبيًا مع مساحة فوق يدك ويظهر الوركان."],
 "Lean back on an incline bench, side-on, with your arm and hip visible.": ["झुकी बेंच पर पीछे टिकें, बगल से, बाँह और कूल्हा दिखे।", "হেলানো বেঞ্চে পিঠ দিয়ে বসুন, পাশ থেকে, হাত ও নিতম্ব দেখা যাক।", "तिरप्या बाकावर मागे टेका, बाजूने, हात आणि नितंब दिसतील.", "వాలు బెంచ్‌పై వెనక్కి ఆనండి, పక్కగా, చేయి, తుంటి కనిపించాలి.", "சாய்வு பெஞ்சில் பின்னால் சாயுங்கள், பக்கவாட்டில், கையும் இடுப்பும் தெரிய வேண்டும்.", "Recuéstate en un banco inclinado, de lado, con brazo y cadera visibles.", "Recline-se num banco inclinado, de lado, com braço e quadril visíveis.", "Bersandar di bangku miring, menyamping, lengan dan pinggul terlihat.", "استند للخلف على مقعد مائل، جانبيًا، بحيث تظهر الذراع والورك."],
}
